return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Swahili','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 15:34+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'sw','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" imehifadhiwa.','"%1$s" created. %2$d template updated.'=>'"%1$s" imetengenezwa. %2$d kiolezo kimesasishwa.' . "\0" . '"%1$s" imetengenezwa. %2$d kiolezo kimesasishwa.','"%s" created.'=>'"%s" imetengenezwa.','%d language not yet linked'=>'Lugha %d bado haijaundwa' . "\0" . 'Lugha %d bado hazijaundwa','%d link updated.'=>'%d kiungo kimesasishwa.' . "\0" . '%d viungo vimesasishwa.','%d locale pack installed.'=>'%d pakiti za lugha zimewekwa.' . "\0" . '%d pakiti za lugha zimewekwa.','%d navigation reference updated.'=>'%d marejeo ya urambazaji yamesasishwa.' . "\0" . '%d marejeo ya urambazaji yamesasishwa.','%d part reference updated.'=>'%d marejeo ya sehemu yamesasishwa.' . "\0" . '%d marejeo ya sehemu yamesasishwa.','%s Archive'=>'Hifadhi %s','(avg %.1f hits/block)'=>'(avg %.1f mafanikio/kipande)','(avg %.1f hits/entry)'=>'(wastani %.1f hits/kuingia)','(disabled)'=>'(imezimwa)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} hayakuwa na viungo vinavyoweza kubadilishwa — chunguza tena kwa uchunguzi)','.txt file(s) in the directory'=>'.txt faili(za) kwenye saraka','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d kiolezo zilizotafsiriwa kutoka kwa mandhari &#8220;%2$s&#8221; zimehifadhiwa kwenye hifadhidata lakini kwa sasa hazifanyi kazi. Zitatumika tena ikiwa utarejesha hali ya mandhari hiyo. Ili kuhamisha tafsiri zako kwa mandhari mpya, zitengeneze tena kupitia <strong>Mipangilio → Lingua Forge → Router → FSE scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> kiungo kinachoweza kurekebishwa kiotomatiki','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> kiungo kinachohitaji mapitio ya mikono','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> njia/nyingine zilizobaki','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> tatizo la kiolezo','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Inakubali faili zilizokusanywa za .mo pekee. Jina la faili lazima zifuate muundo wa {textdomain}-{locale}.mo. Kupakia faili lenye jina sawa na la zamani kutalibadilisha.','Action'=>'Kitendo','Actions'=>'Vitendo','active'=>'kinachofanya kazi','Active Languages'=>'Lugha Zinazotumika','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Lugha zinazotumika: ongeza kila lugha unayotaka kuunga mkono. Kila lugha hupata kiambatanisho cha URL au subdomain na lebo ya hreflang kwenye &lt;head&gt; ya ukurasa.','Active Provider'=>'Mtoa huduma wa Sasa','Add entry'=>'Ongeza kiingilio','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Ongeza maelekezo ili kuboresha rasimu — mfano fupisha, ongeza sehemu ya hitimisho, tumia muundo rasmi zaidi, jumuisha sehemu ya maswali yanayoulizwa mara kwa mara…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Ongeza maelekezo ya kuboresha rasimu — mfano, ifupishe, ongeza sehemu ya hitimisho, tumia muundo rasmi zaidi…','Add new entry'=>'Ongeza kiingilio kipya','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Ongeza neno moja kwa kila mstari. Neno la chanzo na uwasilishaji wa lengo vinahitajika. Jozi ya lugha huamua kazi za tafsiri zinazotumika na masharti.','Adds a link to the home page so visitors can browse in their language.'=>'Ongeza kiungo cha ukurasa wa nyumbani ili wageni waweze kuvinjari kwa lugha yao.','Administrators only (manage_options)'=>'Wasimamizi pekee (simamia_mipangilio)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Baada ya kubadilisha lugha kuu, safisha permalink (sehemu chini) ili kusasisha njia ya URL.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Baada ya kubadilisha mipangilio ya muundo wa URL (kianzio cha njia ↔ subdomain), daima tembelea Mipangilio → Permalinks na bofya Hifadhi Mabadiliko ili kufuta sheria za kuandika upya.','AI Behaviour Preset'=>'Mipangilio ya Tabia za AI','AI cache cleared. %d entry was removed.'=>'Cache ya AI imefutwa. Kipengee %d kiliondolewa.' . "\0" . 'Cache ya AI imefutwa. Vipengee %d vimeondolewa.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'AI Cache: inaorodhesha majibu ya AI yaliyohifadhiwa na idadi za mafanikio. Futa cache yote au vitu vya chapisho kimoja. Tumia "Futa" kabla ya kujaribu mabadiliko ya tafsiri — matokeo yaliyohifadhiwa yanarudiwa hata unapotabadilisha preset au mfano wa AI hadi kifurushi cha cache kitakapotolewa.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Vipengele vya AI ni hiari. Mwelekeo wa lugha, hreflang, kisakinishi cha lugha, na mfumo wa kikundi cha tafsiri vyote vinafanya kazi bila mtoa huduma aliyesakinishwa.','AI Limits & Security'=>'Mipaka na Usalama wa AI','AI provider returned an empty response.'=>'Mtoa huduma wa AI alirudisha majibu tupu.','AI Usage'=>'Matumizi ya AI','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Lenga kwa herufi 120–160. Acha tupu ili kutumia muhtasari wa nyuma.','All time'=>'Wakati wote','Allow editors to lock individual blocks'=>'Ruhusu wahariri kufunga blocks binafsi','Allow Gutenberg template-editing mode on post screens'=>'Ruhusu hali ya uhariri wa template wa Gutenberg kwenye skrini za chapisho','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Pia futa uteuzi wa lugha, uhusiano wa tafsiri, maelezo ya meta, kamusi, na Kumbukumbu ya Tafsiri wakati programu inafutwa.','Also generate meta description'=>'Pia tengeneza maelezo meta','Alternative (server-side):'=>'Mbali (upande wa seva):','An unknown error occurred.'=>'Hitilafu isiyojulikana imetokea.','and'=>'na','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'yote','API calls saved by cache'=>'Vito vya API vilivyohifadhiwa na cache','API Key'=>'Funguo la API','API Keys'=>'Vifunguo vya API','API Keys Tab'=>'Kipindi cha Funguo za API','API Response Cache'=>'Cache ya Majibu ya API','Applied ✓'=>'Imethibitishwa ✓','Apply failed — please try again.'=>'Umeomba kushindwa — tafadhali jaribu tena.','Apply to Block'=>'Tumia kwa Kizuizi','Apply to Editor'=>'Tumia kwa Mhariri','Apply to Footnote'=>'Tumia kwa Nukuu','Apply to Meta Description'=>'Tumia kwa Maelezo ya Meta','Apply translation'=>'Tumia tafsiri','Applying…'=>'Inatumika…','Approximate size'=>'Ukubwa wa takriban','Archive'=>'Makala','Archive: %s'=>'Hifadhi: %s','Authors and above (edit_published_posts)'=>'Waandishi na zaidi (hariri_maandishi_yaliyochapwa)','Behavior'=>'Tabia','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Tabia: chagua preset ya AI (Literal, Balanced, Creative), ongeza maagizo maalum ya tovuti kwa ujumla, wezesha au zima tafsiri ya otomatiki baada ya kuhifadhi chapisho, na weka kumbukumbu ya Tafsiri.','Block Content'=>'Yaliyomo ya Kifungu','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Huonyesha arifa ya heshima wakati ukurasa wa sasa unaonyeshwa kwa lugha yake ya asili kwa sababu hakuna tafsiri inayopo kwa lugha ya mgeni. Inasababishwa na ishara ya LINGUAFORGE_LANG_FALLBACK_ACTIVE ya mtaalamu wa Lingua Forge — haitoi chochote wakati kuna tafsiri kwa eneo la ombi.','Block Editor'=>'Mhariri wa Block','block keywordfallback'=>'kuzingatia','block keywordi18n'=>'i18n','block keywordlanguage'=>'lugha','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'tafsiri','Block locking'=>'Kufunga kwa block','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Mipango ya block zilizoorodheshwa kwa aina za machapisho maalum. Tumia kitufe cha Tafsiri kuunda toleo la lugha. Yaliyomo yaliyotafsiriwa yanahifadhiwa hapa na yanaweza kuhamishwa kwenye chapisho lolote la CPT kutoka kwa mhariri wa block au kutumika kama hatua ya kuanzia kwa Pattern iliyosawazishwa (Reusable Block).','block titleMissing Translation Notice'=>'Arifa ya Tafsiri Iliyokosewa','Block translation reuses'=>'Matumizi ya upya wa tafsiri za blok','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Cache ya tafsiri za kiwango cha blok inayoshirikiana kati ya machapisho. Wakati imewezeshwa, blokii zinazofanana (alama sawa, jozi ya lugha, na kamusi) zinatumikia kutoka kwa kumbukumbu badala ya kuita AI tena. Weka mipangilio katika Mipangilio → Tabia.','Browser language redirect'=>'Uelekeaji wa lugha wa kivinjari','Built-in preset instructions:'=>'Maagizo ya awali yaliyowekwa ndani:','Bulletize (•-prefixed)'=>'Fanya kwa alama za orodha (•-kianzio)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Hifadhi sawa za tafsiri kwenye kiwango cha block ili maudhui yanayoweza kutumika tena (viambatanisho vya chini, upendeleo wa upande, accordions, sehemu za kisheria zenye boilerplate nyingi) zisitoe wito wa API kila wakati. Wakati imewezeshwa, mchakato wa tafsiri huparsing kila chapisho kuwa blocks, huangalia kila block kwenye hifadhi, na hupeleka blocks zisizo na hifadhi pekee kwa AI kwa ombi moja la kundi. Mabadiliko ya kamusi na mabadiliko ya preset ya Uzingatiaji huondoa hifadhi za tafsiri zinazohusika kiotomatiki. Tazama takwimu na safisha hifadhi chini ya Matengenezo.','cached'=>'imehifadhiwa','Cached API responses'=>'Majibu ya API yaliyohifadhiwa','Cached block translations'=>'Tafsiri za blokii zilizohifadhiwa','Cancel'=>'Ghairi','Cannot determine target language from slug.'=>'Haiwezi kubaini lugha lengwa kutoka kwa slug.','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Kataza kiasi cha matumizi ya AI kinachoweza kuzalishwa na tovuti na kuzuia majukumu ya watumiaji wanaoweza kuanzisha simu za AI zilipwa. Inachukua nafasi ya kikomo cha kila mtumiaji (ombi 30 / dakika, kilichowekwa kwa nguvu) kinacholinda dhidi ya mizunguko ya kipekee ya mtumiaji.','chars'=>'wahusika','Chunk translated'=>'Sehemu iliyotafsiriwa','Chunk translated to:'=>'Sehemu iliyotafsiriwa kwa:','Clear'=>'Futa','Clear All'=>'Futa Yote','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Futa matokeo yote ya AI yaliyohifadhiwa? Maombi yajayo yataanzisha wito mpya wa API hadi cache itakapojengwa upya.','Clear API Response Cache'=>'Futa Cache ya Majibu ya API','Clear Debug Files'=>'Futa Faili za Kagua','Clear hints'=>'Futa vidokezo','Clear input'=>'Futa ingizo','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Futa Kumbukumbu ya Tafsiri yote? Tafsiri za baadaye zitajenga tena cache wanapozalishwa.','Clear Translation Memory'=>'Futa Kumbukumbu ya Tafsiri','Close'=>'Funga','Close language panel'=>'Funga paneli ya lugha','Close popover'=>'Funga kidirisha','Compliance Preset'=>'Preset ya Uzingatiaji','Content generated'=>'Yaliyomo yamezalishwa','Content Generator'=>'Kizazi cha Maudhui','Content ready'=>'Yaliyomo yamekamilika','Contributors and above — default (edit_posts)'=>'Wachangia na zaidi — chaguo-msingi (hariri_maandishi)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Dhibiti kiasi cha maudhui yanayopitishwa kwa AI na ukubwa wa majibu yanayoweza kutolewa. Acha uwanja tupu ili kutumia chaguo-msingi cha ndani (kinachoonyeshwa kama mahali pa kuweka). Ongeza thamani hizi ikiwa kurasa kubwa zinakatwa; punguza ili kupunguza gharama za API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Hudhibiti bajeti ya tokeni na mipaka ya ingizo kwa kipengele cha Kizazi cha Maudhui cha AI. Acha mashamba tupu ili kutumia chaguo-msingi zilizojengwa ndani.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Hakikisha kinachotokea wakati msimamizi anafuta programu kutoka kwa Plugins → Plugins zilizowekwa → Futa. Mipangilio ya programu na cache za AI daima zinasafishwa. Uteuzi wa lugha na uhusiano wa tafsiri huzingatiwa kwa chaguo-msingi ili kusudi la kufuta au kufunga upya liweze kuendelea mahali pa kuacha.','Conversational'=>' Mazungumzo','Copied ✓'=>'Imenakiliwa ✓','Copy'=>'Nakili','Copy markup'=>'Nakili muundo wa maandishi','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Nakili matokeo na uyatamise mahali panahitajika (kama moja kwa moja kwenye uwanja wa maelezo mafupi).','Copy to safe storage'=>'Nakili kwenye hifadhi salama','Could not add entry: source term and target term are required.'=>'Haiwezi kuongezea kiingilio: neno la chanzo na neno la malengo linahitajika.','Could not copy the file. Check that the uploads folder is writable.'=>'Haiwezekani kunakili faili. Hakikisha folda ya uploads ina haki ya kuandika.','Could not instantiate the provider.'=>'Haiwezi kuanzisha mtoa huduma.','Could not save the file. Check that the uploads folder is writable.'=>'Haiwezekani kuhifadhi faili. Hakikisha folda ya uploads ina haki ya kuandika.','Could not save the glossary entry.'=>'Haiwezi kuokoa kiingilio cha kamusi ya msamiati.','CPT Block Patterns'=>'Mipango ya Block CPT','Create'=>'Unda','Create missing'=>'Unda zilizokosewa','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Kuunda tafsiri za aina ya chapisho "%s" kunahitaji muunganisho hai. Tafadhali hakikisha muunganisho unaohitajika umewekwa na kufanya kazi.','Creating…'=>'Inaundwa…','Creative / Marketing'=>'Ubunifu / Masoko','Creative / Marketing instructions'=>'Maagizo ya Ubunifu / Masoko','Current content (will be overwritten)'=>'Yaliyomo ya sasa (yatafutwa)','Current title'=>'Kichwa cha sasa','Current: {current}'=>'Sasa: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Kwa sasa urithi kutoka kwa kifungo cha %s. Kuchagua thamani hapa kutaleta mabadiliko.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Kwa sasa inakosewa kwa posts zinazotumia vigezo vya placeholder vya block-comment (wp:details fields za muhtasari, n.k.) — zinapita kwa njia ya tafsiri ya wito mmoja iliyopo.','Currently:'=>'Sasa hivi:','Custom'=>'Maendeleo Maalum','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Kiwango cha AI cha kila siku kimefikia (%1$d maombi). Kinarejeshwa saa %2$s UTC.','Daily request limit'=>'Kikomo cha maombi ya kila siku','Debug Files'=>'Faili za Kagua','Debug files cleared. %d file was removed.'=>'Faili za kagua zimesafishwa. Faili %d imeondolewa.' . "\0" . 'Faili za kagua zimesafishwa. Faili %d zimeondolewa.','Debug logging'=>'Kumbukumbu za kagua','Debug logging disabled.'=>'Kumbukumbu za kagua zimezimwa.','Debug logging enabled.'=>'Kumbukumbu za kagua zimewezeshwa.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Kagua: wezesha rekodi ya kagua ili kukamata maombi ya AI na majibu ya API kwa faili la ndani. Zima baada ya utatuzi wa matatizo — hali ya kagua inaandika faili kwa kila ombi la AI.','Delete'=>'Futa','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Futa faili zote za .txt kwenye saraka ya kagua? Saraka yenyewe itabaki ili kuendelea kuandika mafaili ya kagua ya baadaye.','Delete all files for this override (both .mo and .po)?'=>'Futa faili zote za mabadiliko haya (zote .mo na .po)?','Delete content data on uninstall'=>'Futa data ya maudhui wakati wa kufuta','Delete this glossary entry?'=>'Unataka kufuta kiingilio hiki cha kamusi? ','Describe what to write — topic, key points, structure…'=>'Eleza kinachopaswa kuandikwa — mada, vidokezo muhimu, muundo…','Directory'=>'Saraka','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Zima wakati wa kurekebisha maombi au unapoihitaji kila ombi lifikie mtoa huduma wa AI. Kuzima hakufutii vitu vilivyohifadhiwa — kuirudisha tena huwarejesha. Kuongeza matumizi ya API mara moja kwenye tovuti zenye shughuli nyingi kunatarajiwa wakati imezimwa.','Display'=>'Onyesha','Displays the Lingua Forge language switcher.'=>'Inaonyesha kigeuzi cha lugha cha Lingua Forge.','Documentation'=>'Nyaraka','Done'=>'Imekamilika','Done — {done} of {total} post(s) fixed.'=>'Imekamilika — machapisho {done} kati ya {total} yamerekebishwa.','Down'=>'Chini','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Pakua na usakinishe pakiti ya lugha kuu ya WordPress moja kwa moja kutoka WordPress.org. Mara baada ya kusakinisha, lugha inapatikana kwa uelekezaji wa URL na mchakato wa tafsiri wa AI. Orodha ya lugha zinazopatikana inachukuliwa kwa ombi — bofya kitufe chini ili kuipakua.','Dropdown direction'=>'Mwelekeo wa orodha','Editors and above (edit_others_posts)'=>'Wahariri na zaidi (hariri_wa_waandishi_wengine)','Enable API response caching'=>'Wezesha kuhifadhi majibu ya API','Enable block-level translation cache reuse across posts'=>'Wezesha upyaji wa hifadhi ya tafsiri kwenye block kwa posts','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Ingiza ufunguo wako wa API kwa angalau mtoa huduma mmoja wa AI. Funguo zimehifadhiwa kwa usalama kwa kutumia AES-256-GCM na siri maalum ya tovuti (LINGUAFORGE_SECRET). Usishiriki usafirishaji wa hifadhidata bila kubadilisha siri kwanza.','environment variable'=>'mabadiliko ya mazingira','Error'=>'Hitilafu','Expand'=>'Panua','Expected: {expected}'=>'Inatarajiwa: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'Msaada wa ziada — sauti, mtindo, vizuizi, hadhira lengwa…','Extra guidance — tone, style, constraints…'=>'Msaada wa ziada — sauti, mtindo, vizuizi…','Failed. Please try again.'=>'Imeshindwa. Tafadhali jaribu tena.','Feature'=>'Kipengele','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Vipengele vimegawanywa katika ngazi mbili. Ingiza kitambulisho halisi cha mfano kwa kila ngazi na mtoa huduma. Acha uwanja tupu ili kutumia chaguo-msingi cha ndani (kinachoonyeshwa kama nafasi ya kujaza). Mifano ya mtoa huduma anayeendesha pekee ndiyo inaitwa wakati wa runtime — weka zingine mapema ikiwa unakusudia kubadilisha.','File copied to safe storage successfully.'=>'Faili imehamishwa kwa mafanikio kwenye hifadhi salama.','Files'=>'Faili','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Faili huwasili kwenye saraka iliyo chini. Inafaa kwa utatuzi wa matatizo ya tafsiri — zima mara unapata unachohitaji ili faili zisikusanyike. Pia unaweza kuizuia kutoka wp-config.php kwa kutumia `define( \'LINGUAFORGE_AI_DEBUG\', true );` ambayo inazidi kitufe hiki.','Filter'=>'Kichujio','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Chuja kwa kutumia linguaforge_debug_dir ili kuelekeza matokeo ya kagua mahali pasipo umma.','Fix'=>'Rekebisha','Fix All'=>'Rekebisha Yote','Fix all links'=>'Rekebisha viungo vyote','Fix all parts'=>'Rekebisha sehemu zote','Fix Links'=>'Rekebisha Viungo','Fix Nav'=>'Rekebisha Urambazaji','Fix Parts'=>'Rekebisha Sehemu','Fix Template'=>'Rekebisha Kiolezo','Fixing {n} / {total}…'=>'Rekebisha {n} / {total}…','Fixing…'=>'Inarekebishwa…','Flush Permalink Rules'=>'Fanya usafi wa Sheria za Permalink','Flush Permalinks'=>'Fanya usafi wa Permalinks','Footnote Content'=>'Maudhui ya Nukuu','footnote(s) translated — applied together with content.'=>'Vijisehemu vilivyotafsiriwa — vimewekwa pamoja na yaliyomo.','Footnotes'=>'Vijisehemu','Footnotes payload (advanced)'=>'Msaada wa maelezo ya mguu wa ukurasa (ya juu)','Forbidden'=>'Kizuizi','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Imezimwa kwa nguvu na mabadiliko ya LINGUAFORGE_AI_DEBUG katika wp-config.php. Ondoa mstari huo ili kudhibiti kitufe hiki kutoka hapa.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Imezuiwa kwa nguvu na mabadiliko ya LINGUAFORGE_AI_DEBUG katika wp-config.php. Ondoa mstari huo ili kudhibiti kitufe hiki kutoka hapa.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Imepatikana {parts} kati ya <strong>{total}</strong> ya machapisho <strong>{scanned}</strong> yaliyopitiwa kwa <strong>{lang}</strong>.','From'=>'Kutoka','Front Page'=>'Ukurasa wa Mbele','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Uwezo wa FSE: tengeneza, tafsiri, na rekebisha viungo katika templates za Full Site Editing na sehemu za templates moja kwa moja kutoka kwa tab hii.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Mifano ya FSE iliyopandikizwa kutoka kwa mandhari hai. Unda kisha ibadilike kwenye Mhariri wa Tovuti.','Full Article'=>'Makala Kamili','Full post'=>'Ujumbe kamili','General'=>'Jumla','Generate'=>'Tengeneza','Generate Content'=>'Tengeneza Yaliyomo','Generate content…'=>'Tengeneza maudhui…','Generate Excerpt'=>'Unda Kipengele','Generate Meta Description'=>'Unda Maelezo Meta','Generated Content'=>'Yaliyomo yaliyotengenezwa','Generated meta description'=>'Maelezo ya meta yaliyotengenezwa','Generating…'=>'Inazalishwa…','Generation failed.'=>'Uzalishaji umeshindwa.','Getting started'=>'Anza','Global AI preset'=>'Preset ya AI Ulimwenguni','Global default (%s)'=>'Chaguo-msingi duniani kote (%s)','Glossary'=>'Kamusi','Glossary entry added.'=>'Kuingiza kamusi ya msamiati kumetokea.','Glossary entry removed.'=>'Kufuta kamusi ya msamiati.','Glossary Tab'=>'Tabu ya Kamusi','Google (Gemini)'=>'Google (Gemini)','Hide'=>'Ficha','Hints'=>'Vidokezo','Home link text'=>'Maandishi ya kiungo cha nyumbani','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Jinsi inapaswa kuonekana katika tafsiri. Andika thamani ile ile na neno la chanzo ili kuagiza AI kuilinda kwa maneno halisi.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Picha + lebo','Icon only'=>' Picha pekee','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Ikiwa imeshakaguliwa, kufuta programu kutafuta kwa muda mrefu utafuta uteuzi wa lugha, uhusiano wa tafsiri, maelezo ya meta, mipangilio ya ukurasa, kamusi ya AI, na Kumbukumbu ya Tafsiri kwa kila chapisho kwenye tovuti hii. Hii haiwezi kurejeshwa. Acha ishiwi isipokuwa unatoa msaada wa lugha nyingi kutoka kwa tovuti.','Improve writing'=>'Boresha uandishi','Informative'=>'Taarifa','Input tokens'=>'Token za ingizo','Install'=>'Sakinisha','Install a Language'=>'Sakinisha Lugha','Installing…'=>'Inasakinishwa…','Instructions (optional)'=>'Maagizo (hiari)','Instructions / key points'=>'Maagizo / vidokezo muhimu','Integration API'=>'API ya Uunganisho','Internal Link Fixer'=>'Rekebisha Kiungo cha Ndani','Introduction only'=>'Utangulizi tu','Invalid file reference.'=>'Rejea ya faili si sahihi.','Invalid filename.'=>'Jina la faili si sahihi.','Invalid language.'=>'Lugha si sahihi.','Invalid locale code.'=>'Msimbo wa lugha si sahihi.','Invalid or primary language.'=>'Lugha si sahihi au ni kuu.','Invalid post type.'=>'Aina ya chapisho si sahihi.','Invalid template part.'=>'Sehemu ya kiolezo si sahihi.','Invalid template type.'=>'Aina ya kiolezo si sahihi.','Key points, ideas, or structure to build from…'=>'Vitu muhimu, mawazo, au muundo wa kujenga kutoka...','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Vifunguo vinahifadhiwa kwa usalama kwa AES-256-CBC kabla havijasomwa kwenye hifadhidata ya WordPress. Siri ya usimbuaji inatokana na chumvi za uthibitishaji wa WordPress (wp-config.php), kwa hivyo funguo za maandishi hayagusi hifadhidata kamwe.','Language'=>'Lugha','Language %s installed successfully.'=>'Lugha %s imewekwa kwa mafanikio.','Language (optional)'=>'Lugha (hiari)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Sakinisho la lugha limezimwa kwenye seva hii (DISALLOW_FILE_MODS imewekwa).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Sakinisho la lugha limezimwa kwenye seva hii. Kigezo cha DISALLOW_FILE_MODS kimewekwa katika wp-config.php. Sakinisha pakiti za lugha kwa mikono kupitia WP-CLI: wp language core install de_DE','Language label'=>'Lebo ya lugha','Language Overrides'=>'Mabadiliko ya Lugha','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Mabadiliko ya Lugha: simamia faili za mabadiliko maalum za .po/.mo kwa mistari ya UI ya Lingua Forge. Tumia hii badala ya kuhariri faili za programu moja kwa moja — mabadiliko yanadumu baada ya masasisho.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Sakinisho la pakiti ya lugha limegonga. Lugha inaweza tayari imewekwa, msimbo wa lugha si sahihi, au seva yako inazuia uandishi wa faili.','Language Setup'=>'Mipangilio ya Lugha','Language Switcher'=>'Kigeuzi cha Lugha','Language switcher'=>'Kisakinishi cha Lugha','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Nakili za lugha maalum za mandhari. Mara baada ya kuundwa, templates huboreshwa kurejelea sehemu maalum za lugha.','Language:'=>'Lugha:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Lugha zinazojulikana kwa sasa kwa router (zinatokana na pakiti za lugha za WordPress zilizowekwa pamoja na lugha kuu). Weka pakiti za lugha za ziada katika sehemu iliyo chini ili kufanya lugha zaidi zipatikane kwa uelekezaji na tafsiri.','Last 30 days'=>'Siku 30 zilizopita','Last 7 days'=>'Siku 7 zilizopita','Lead paragraph (≤60 w)'=>'Kipande cha kuongoza (≤60 w)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Acha uwanja wa mfano ukiwa tupu ili utumie chaguo-msingi cha ndani kwa kiwango hicho. Maandishi ya placeholder yanaonyesha mfano wa mfano utakaotumika.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Acha tupu kwa majina ya chapa na maneno yasiyotegemea lugha ambayo yanapaswa kutekelezwa bila kujali lugha tunayotafsiri kutoka.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Acha tupu ili kiingilio hiki kiweze kutumika kwa lugha zote za malengo — bora kwa majina ya chapa, kifupi, na maneno yanayopaswa kuhifadhiwa kwa maneno halisi katika kila tafsiri.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Acha tupu ili kuhifadhi funguo iliyopo. Ingiza thamani mpya kuibadilisha.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Acha tupu ili kutumia chaguo-msingi cha kujengwa ndani. Kufuta chaguo lililohifadhiwa kunarudisha chaguo-msingi wakati wa hifadhi inayofuata.','Legal / Compliance'=>'Kisheria / Uzingatiaji','Legal / Compliance instructions'=>'Maagizo ya Kisheria / Uzingatiaji','Light'=>'Nuru','Light (default — fast and cost-effective)'=>'Nuru (chaguo-msingi — haraka na yenye gharama nafuu)','Light (fast and cost-effective — Haiku / Flash)'=>'Mwanga (haraka na nafuu — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Nuru: inatumika kwa maelezo mafupi na uzalishaji wa excerpt — haraka, gharama ya chini.','Limit results to pages in the given Lingua Forge language code.'=>'Lenga matokeo kwa kurasa zilizo katika msimbo wa lugha wa Lingua Forge uliotolewa.','Limits'=>'Mipaka','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge huongeza mwelekeo wa lugha nyingi, tafsiri yenye nguvu ya AI, tags za SEO za hreflang, na kisakinishi cha lugha kwenye tovuti yako ya WordPress.','Lingua Forge AI Tools'=>'Vifaa vya Lingua Forge AI','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge inazuia vipengele viwili vya Gutenberg kwa chaguo-msingi ili kuweka tabia ya uhariri kuwa thabiti kati ya lugha. Chagua hapa ikiwa unahitaji uwezo kamili wa Gutenberg / FSE.','Lingua Forge Settings'=>'Mipangilio ya Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge hutumia safu mbili za cache huru ili kuepuka kuita API za AI mara kwa mara. Tumia vivinjari hapa chini kuangalia na kusimamia kila moja.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge hutumia safu mbili za mfano kwa kila mtoa huduma:','Lingua Forge — Quick Translate'=>'Lingua Forge — Tafsiri Haraka','Lingua Forge — Settings'=>'Lingua Forge — Mipangilio','link(s)'=>'kiungo(viungo)','Links'=>'Viungo','Load available languages'=>'Pakua lugha zinazopatikana','Loading…'=>'Inapakia…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate hifadhi tafsiri zake maalum katika wp-content/languages/loco/ — mahali ambapo inaweza kufutwa kwa kimya na sasisho la WP, kufanywa upya kwa programu, au ikiwa Loco Translate yenyewe inatoweka. Nakili faili hapa huziweka kwenye saraka ya Lingua Forge i18n-overrides, ambayo huendelea kuwa hai kupitia matukio yote hayo na hujumuishwa kiotomatiki kila wakati.','Loco Translate — Copy to Safe Storage'=>'Loco Tafsiri — Nakili kwa Hifadhi Salama','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Uwezo wa WordPress wa chini kabisa unaoruhusiwa kuanzisha vipengele vya AI. Kuimarisha hili kwenye tovuti za waandishi wengi kunazuia Wachangia au akaunti za majaribio kuendesha simu za AI zilipwa. Pitia kwa kila kipengele kupitia kichujio cha "linguaforge_required_capability".','Maintenance'=>'Matengenezo','Maintenance Tab'=>'Tabu ya Matengenezo','Make casual'=>'Fanya kwa kawaida','Make concise'=>'Fupisha','Make formal'=>'Fanya rasmi','Mark citations needed'=>'Alama za kuashiria mahitaji ya nukuu','Max context characters'=>'Wahusika wa muktadha wa juu zaidi','Max hints characters'=>'Wahusika wa vidokezo vya juu zaidi','Max input characters'=>'Herufi za ingizo za juu zaidi','Max output tokens'=>'Idadi ya tokeni za matokeo makubwa','Maximum characters accepted from the input field. Default: 8 000.'=>'Wahusika wa juu zaidi wanaokubaliwa kutoka kwa uwanja wa ingizo. Chaguo-msingi: 8,000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Wahusika wa juu zaidi wa maudhui ya chapisho yaliyopo yanayotumwa kwa AI kama muktadha wa mbegu wakati hakuna Vidokezo vinavyotolewa. Chaguo-msingi: 6,000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Wahusika wa juu zaidi wanaosomwa kutoka kwa uwanja wa Vidokezo. Chaguo-msingi: 2,000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Kiwango kikubwa cha wahusika wa maudhui ya chapisho yaliyotumwa kwa AI. 0 inamaanisha hakuna kikomo — maudhui kamili yanatumiwa daima (inapendekezwa). Weka thamani isiyo sifuri ikiwa mtoa huduma wako ana dirisha la muktadha mkali. Onyo linaandikwa kwenye kumbukumbu ya makosa ya PHP kila wakati maudhui yanapunguzwa.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Idadi kubwa ya tokeni ambazo AI inaweza kuzalisha kwa jibu moja la tafsiri. Ikiwa tafsiri inakatwa kimya kimya mwisho, ongeza thamani hii. Chaguo-msingi: 16,000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Wahusika wa juu zaidi wanaowezekana na AI wanaweza kuzalisha kwa kila uendeshaji wa kizazi. Ongeza ikiwa makala kamili yanakatwa. Chaguo-msingi: 8,192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Wahusika wa juu zaidi wanaowezekana na AI inaweza kuzalisha kwa kila tafsiri ya haraka. Chagua: 2,000.','Meta Description'=>'Maelezo ya Meta','Meta Description, Excerpt Generator'=>'Maelezo ya Meta, Mwandishi wa Muhtasari','Minimum role'=>'Hali ya chini','Missing pattern name or language.'=>'Jina la muundo au lugha inakosekana.','Mode'=>'Hali','Model'=>'Mfano','Model tier'=>'Kiwango cha mfano','Models'=>'Miundo','Models Tab (General)'=>'Tabu ya Mifano (Kwa Jumla)','Most recent cached block'=>'Blokii ya hivi karibuni iliyohifadhiwa','Most recent cached response'=>'Majibu ya hivi karibuni yaliyohifadhiwa','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Usanifu wa lugha nyingi, alama za meta za SEO, na zana za maudhui za AI kwa WordPress. Inachanganya utambuzi wa lugha, usafirishaji wa URL, hreflang, maelezo ya meta, na sifa za kukata, meta, na tafsiri zinazotumiwa na AI.','Name displayed in this language. Leave empty to use the source name.'=>'Jina linaloonyeshwa kwa lugha hii. Acha tupu ili kutumia jina la chanzo.','Navigation'=>'Urambazaji','Navigation has no content to translate.'=>'Uelekeo haujakuwa na maudhui ya kutafsiri.','Navigation not found.'=>'Uelekeo haujapatikana.','Navigation posts are translated via the Router tab, not this button.'=>'Maandishi ya urambazaji yanatafsiriwa kupitia kichupo cha Router, si kitufe hiki.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Utaratibu wa urambazaji unahitaji mtoa huduma wa AI anayeishi. Sanidi ufunguo wa API kwenye kichupo cha Funguo za API.','Navigations'=>'Viongozi','Network error — could not reach the WordPress AJAX endpoint.'=>'Hitilafu ya mtandao — haikuweza kufikia mwisho wa AJAX wa WordPress.','No %s version found in this translation group.'=>'Hakuna toleo la %s lililopatikana katika kundi hili la tafsiri.','No AI provider configured.'=>'Mtoa huduma wa AI hajaanzishwa.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Hakuna matumizi ya AI yaliyorekodiwa katika dirisha lililochaguliwa (%s). Chagua wingi zaidi juu.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Hakuna matumizi ya AI yaliyorekodiwa bado. Mara editor anapofanya tafsiri, kuunda maelezo ya meta, au kutumia kipengele kingine cha AI, jumla zitajitokeza hapa.','No API key configured for this provider.'=>'Hakuna funguo ya API iliyowekwa kwa mtoa huduma huu.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Hakuna maagizo yaliyowekwa ndani — kila kipengele cha AI kinatumia chaguo zake zilizobinafsishwa. Jaza uwanja wa Maagizo ya Maelekezo ya Maoni ya Kibinafsi hapa chini ili kuongeza kanuni zako za tovuti kwa ujumla.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Hakuna faili maalum za Loco Translate bado. Zinaonekana hapa mara tu unapohifadhi tafsiri kwenye Loco Translate.','No file was selected.'=>'Hakuna faili iliyochaguliwa.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Hakuna viingilio vya kamusi vinavyolingana na kichujio cha sasa. Futa kichujio ili kuona viingilio vyote, au ongeza kiingilio kipya chini.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Hakuna viingilio vya kamusi bado. Weka chini ili kuanza kutekeleza istilahi katika tafsiri.','No internal links found to update.'=>'Hakuna viungo vya ndani vilivyopatikana vya kusasisha.','No language-specific template parts found to map.'=>'Hakuna sehemu za kiolezo zinazohitajika kubadilishwa ili kuoanisha.','No navigation references needed updating.'=>'Hakuna marejeo ya urambazaji yanayohitajika kusasishwa.','No override files uploaded yet.'=>'Hakuna faili za mabadiliko zilizopakiwa bado.','No response from provider — check the error log for details.'=>'Hakuna majibu kutoka kwa mtoa huduma — angalia kumbukumbu za makosa kwa maelezo.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Hakuna lugha za ziada zilizowekwa. Sakinisha pakiti ya lugha hapo juu ili kuwezesha muundo wa kiolezo.','No source content found to translate.'=>'Hakuna maudhui ya chanzo yaliyopatikana ya kutafsiri.','No source page linked yet.'=>'Bado hakuna ukurasa wa chanzo umeunganishwa.','No template part references needed updating.'=>'Hakuna marejeo ya sehemu za kiolezo zinazohitajika kusasishwa.','No {lang} translation registered (TRID missing)'=>'Hakuna tafsiri ya {lang} iliyosajiliwa (TRID inakosekana)','Notes'=>'Maelezo','Notice message'=>'Ujumbe wa arifa','Notice settings'=>'Mipangilio ya arifa','Oldest cached block'=>'Blokii ya zamani zaidi iliyohifadhiwa','Oldest cached response'=>'Majibu ya zamani zaidi yaliyohifadhiwa','Only .mo files are accepted.'=>'Faili za .mo pekee zinakubaliwa.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Muktadha wa hiari kwa wahariri (kama vile "ASIC = Circuit ya Maombi Mahususi; ihifadhi kwa Kiingereza katika muktadha wa kiufundi").','Output'=>'Matokeo','Output tokens'=>'Token za matokeo','overridden'=>'kimezuiwa','Override file deleted.'=>'Faili ya mabadiliko imefutwa.','Override file uploaded successfully.'=>'Faili ya mabadiliko imepakuliwa kwa mafanikio.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Inabadilisha mipangilio ya AI kwa Tafsiri na Uundaji wa Maudhui kwenye ukurasa huu. Vipengele vingine vyote vinatumia mipangilio ya jumla kila wakati.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Inabadilisha mipangilio ya AI kwa Tafsiri na Uundaji wa Maudhui kwenye ukurasa huu. Maagizo ya maoni maalum ya tovuti yote (Mipangilio → Tabia) yanajumuishwa kila wakati kwenye kila ombi bila kujali chaguo hili.','Overview'=>'Muhtasari','Page'=>'Ukurasa','Part'=>'Sehemu','Paste a footnote, sentence, or any snippet here…'=>'Bandika nukuu ya mguu wa ukurasa, sentensi, au kipande chochote hapa...','Paste text, or select text in the editor first…'=>'Bandika maandishi, au chagua maandishi kwenye mhariri kwanza…','Paste text, or select text on the page first…'=>'Bandika maandishi, au chagua maandishi kwenye ukurasa kwanza…','Paste your API key…'=>'Bandika funguo lako la API…','Path prefix — example.com/de/'=>'Kipindi cha njia — example.com/de/','Pattern'=>'Mfano','Pattern has no content to translate.'=>'Muundo haujashikilia maudhui ya kutafsiriwa.','Pattern not found.'=>'Muundo haujapatikana.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Muundo umetafsiriwa na kuhifadhiwa. Nakili maudhui kwenye chapisho lako la CPT kupitia mhariri wa kiolezo au tumia kama mwanzo wa Kiolezo kinachoweza kutumika tena.','Pattern translation failed.'=>'Ufasirishwa kwa mfano umeshindwa.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'Cache ya kila chapisho kwa tafsiri zinazozalishwa na AI, maelezo ya meta, excerpt, na maudhui. Inafanya kazi daima — hakuna kitufe tofauti cha kugeuza. Vitu vinavunjwa kiotomatiki wakati wa maudhui au mtoa huduma wa AI/mfano unabadilika. Tumia kitufe cha \'↺ Tafsiri tena\' kwenye upau wa zana au bofya Futa chini ili kulazimisha wito mpya wa API.','Permalink rules flushed successfully.'=>'Sheri za permalink zimefutwa kwa mafanikio.','Permission denied.'=>'Ruhusa imekatwa.','Persuasive'=>'Ushawishi','PHP constant'=>'kifungo cha PHP','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Weka maneno ambayo hayapaswi kutafsiriwa au lazima yatangazwe kwa njia fulani (k.m. majina ya chapa, majina ya bidhaa, maneno mafupi). Mipaka ya kamusi huingizwa katika kila ombi la tafsiri la AI kwa ajili ya vipengele vyote: tafsiri ya chapisho, maelezo ya meta, excerpt, na tafsiri ya template ya FSE.','Plain language'=>'Lugha rahisi','Please enter some instructions first…'=>'Tafadhali ingiza maagizo kwanza…','Please enter some text first…'=>'Tafadhali ingiza maandishi kwanza…','Post'=>'Uchapishaji','Post not found.'=>'Chapisho hakipatikani.','Post Types'=>'Aina za Machapisho','Prefilled from excerpt. Edit to override.'=>'Imejazwa kutoka kwa muhtasari. Badilisha ili kuizidi.','Primary Language'=>'Lugha Kuu','Primary language'=>'Lugha kuu','Primary language saved.'=>'Lugha kuu imehifadhiwa.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Lugha kuu: lugha ambayo maudhui yako ya sasa yameandikwa. Tafsiri zote hutoka kwa lugha hii; kubadilisha hakusababishi kuhamisha au kufuta machapisho yoyote.','Processing…'=>'Inashughulikiwa…','Provider'=>'Mtoa huduma','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Mtoa huduma haukutoa maandishi. Angalia kumbukumbu za makosa za WordPress kwa sababu kamili ya kushindwa.','Quality'=>'Ubora','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Ubora (chaguo-msingi — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Ubora (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Ubora: hutumika kwa tafsiri ya chapisho na uzalishaji wa maudhui — ubora wa juu, gharama ya juu.','Quick Translate'=>'Tafsiri Haraka','Quick Translation'=>'Tafsiri Haraka','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Tafsiri Haraka hutumiwa kwa hali ya vipande/vipande — vifungu vifupi vinavyotafsiriwa kwa ombi kutoka kwa upau wa zana, mhariri, au popo za kizuizi. Inatumia usanidi tofauti, nyepesi kutoka kwa tafsiri ya ukurasa kamili ili kuweka majibu kuwa ya haraka na yenye gharama nafuu.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Inarudisha tena Gutenberg\'s canLockBlocks. Inafaa kwa templates za uhariri zinazohitaji kuzuia wachangiaji kuhamisha au kufuta blocks fulani.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Inarudisha tena supportsTemplateMode. Muhimili kwa mchakato wa Uhariri wa Tovuti Kamili ambapo ubadilishaji wa template wa kiwango cha chapisho ni nia.','Re-generates and updates the cached result.'=>'Inazalisha tena na kusasisha matokeo yaliyohifadhiwa.','Re-scan'=>'Re-scan','Re-scanning…'=>'Inasoma tena...','Re-translate'=>'Tafsiri tena','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Uelekeza wageni kwa lugha yao wanayoipendelea kulingana na kichwa cha Accept-Language cha kivinjari','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Boresha zaidi — mfano "fupisha" au "tumia sauti rasmi"…','Refine further:'=>'Boresha zaidi:','Refinement'=>'Uainishaji','Refinement failed — please try again.'=>'Uainishaji umeshindwa — tafadhali jaribu tena.','Refining…'=>'Inasafishwa…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Inarejesha sheria za uandishi wa WordPress ili viambishi vya URL, slug za lugha, na uandishi wa makala viwe vinaendana. Inahitajika baada ya kubadilisha lugha kuu au kuongeza msaada wa lugha mpya.','Remove stored key'=>'Ondoa funguo iliyohifadhiwa','Report an issue on GitHub'=>'Ripoti tatizo kwenye GitHub','Request failed — please try again.'=>'Ombi limekosewa — tafadhali jaribu tena.','Request failed.'=>'Ombi limekosewa.','Request failed. Check your connection.'=>'Ombi limeshindwa. Angalia muunganisho wako.','Request failed. Please try again.'=>'Ombi limeshindwa. Tafadhali jaribu tena.','Requests'=>'Maombi','Reset'=>'Washa upya','Result will appear here…'=>'Matokeo yataonekana hapa…','Retranslate'=>'Tafsiri tena','Retranslating…'=>'Inatafsiri tena…','Review carefully — links and slugs not updated.'=>'Kagua kwa makini — viungo na slugs havijasasishwa.','Review translation before applying'=>'Kagua tafsiri kabla ya kutumia','Revise'=>'Rekebisha','Revision'=>'Uboreshaji','Revision Type'=>'Aina ya Uboreshaji','Router'=>'Router','Router Tab'=>'Tabu ya Router','Save Debug Setting'=>'Hifadhi Mipangilio ya Kagua','Save Router Settings'=>'Hifadhi Mipangilio ya Router','Save Settings'=>'Hifadhi Mipangilio','Save the post to persist changes.'=>'Hifadhi chapisho ili kudumisha mabadiliko.','Save Uninstall Setting'=>'Hifadhi Mipangilio ya Kufuta','Saved to the meta description field when you apply.'=>'Imehifadhiwa kwenye uwanja wa maelezo ya meta unapoomba.','Scan failed: '=>'Uchunguzi umeshindwa: ','Scan request failed. Please try again.'=>'Ombi la uchunguzi limekosa mafanikio. Tafadhali jaribu tena.','Scanning posts for broken language links…'=>'Inasoma machapisho kwa ajili ya viungo vya lugha vilivyovunjika...','Search'=>'Tafuta','Search Results'=>'Matokeo ya Utafutaji','Security check failed — file path is not permitted.'=>'Uhakiki wa usalama umeshindwa — njia ya faili haikubaliki.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Chagua lugha ili kuendesha muundo wa FSE, sehemu za muundo, na menyu za urambazaji.','Select language'=>'Chagua lugha','SEO character-count info'=>'Habari za idadi ya wahusika za SEO','Server setup (subdomain)'=>'Mipangilio ya seva (subdomain)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Huweka tabia chaguo-msingi ya AI kwa vipengele vyote vya tovuti. Chapisho binafsi kinaweza kubadilisha hii kwa Tafsiri na Uundaji wa Maudhui kupitia sanduku la meta la Lingua Forge.','Settings'=>'Mipangilio','Settings saved.'=>'Mipangilio imehifadhiwa.','Show home link'=>'Onyesha kiungo cha nyumbani','Shown when no translation exists for the visitor\'s language.'=>'Unaonyeshwa wakati hakuna tafsiri inayopo kwa lugha ya mgeni.','Single'=>'Moja','Single %s'=>'Moja %s','Single: %s'=>'Moja: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Kikomo cha tovuti kwa maombi ya AI kwa siku ya UTC (kinahesabu tafsiri za Zana na marekebisho ya kizuizi). Kiwango kinarejeshwa saa sita usiku wa UTC. Weka 0 ili kuzima kikomo.','Size'=>'Ukubwa','Some link fixes failed.'=>'Baadhi ya marekebisho ya viungo yameshindwa.','Some nav ref fixes failed.'=>'Marekebisho ya marejeo ya urambazaji yameshindwa.','Some part fixes failed.'=>'Sehemu zingine hazikuweza kurekebishwa.','Some parts could not be created.'=>'Sehemu zingine hazikuweza kuundwa.','Some templates could not be created.'=>'Baadhi ya kiolezo hakikuweza kuundwa.','Some translations failed.'=>'Baadhi ya tafsiri zimeshindwa.','Source file not found.'=>'Faili ya chanzo haipatikani.','Source lang'=>'Lugha ya Chanzo','Source language'=>'Lugha ya Chanzo','Source term'=>'Neno la Chanzo','Standard'=>'Kawaida','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Kawaida hutumia joto la kila kipengele kilichopimwa: Tafsiri T=0.2 (sahihi), Tafsiri Haraka T=0.4, Mwandishi wa Maudhui T=0.6 (ubunifu). Preset nyingine hutumia joto moja lililowekwa kwa vipengele vyote.','Status'=>'Hali','Status / Actions'=>'Hali / Vitendo','Storytelling'=>'Hadithi','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Hali kali ya uhifadhi kwa maudhui ya kisheria, kanuni, matibabu, au ya kiufundi. Wakati iko, kila kipengele cha AI kinatumia joto la sampuli ya chini na huongeza kifungu cha chini kwa amri ya mfumo — istilahi, nambari za makala, vitengo, majina ya chapa, na lugha za kanuni huhifadhiwa verbatim badala ya kufupishwa.','Structured Outline'=>'Muhtasari wa Muundo','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Mode ya subdomain inahitaji seva yako ya wavuti kuelekeza subdomains zote za lugha (kama de.example.com) kwa usakinishaji huu wa WordPress. Baada ya kubadilisha mode, fanya usafi wa sheria za permalink na safisha cache yoyote. Ikiwa URL yako ya nyumbani inajumuisha www (kama www.example.com), tumia kichujio cha lf_base_domain kuweka domain kuu bila www ili subdomains zifanywe kwa usahihi.','Subdomain — de.example.com/'=>'Subdomain — de.example.com/','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Watoa huduma wanaotegemewa: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Mtoa huduma mmoja tu anafanya kazi kwa wakati mmoja. Chagua mtoa huduma anayeendelea kwenye tabu ya Jumla.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, kwa kila kipengele','Target lang'=>'Lugha ya Malengo','Target Language'=>'Lugha inayolengwa','Target language'=>'Lugha ya Malengo','Target term'=>'Neno la Malengo','Target: 140–160 chars for optimal SERP display'=>'Lengo: wahusika 140–160 kwa kuonyesha bora kwenye SERP','Technical'=>'Kitaaluma','Technical / Scientific'=>'Kitaaluma / Sayansi','Technical / Scientific instructions'=>'Maagizo ya Kiufundi / Sayansi','Template "%s" already exists.'=>'Kiolezo "%s" tayari kipo.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Kiolezo "{expected}" hakipo — tengeneza kwanza kwenye Mhariri wa Tovuti.','Template has no content.'=>'Kiolezo hakina maudhui.','Template mode'=>'Hali ya template','Template not found or not stored in the database.'=>'Kiolezo hakipatikani au hakijahifadhiwa kwenye hifadhidata.','Template part "%s" already exists.'=>'Sehemu ya kiolezo "%s" tayari kipo.','Template part has no content.'=>'Sehemu ya kiolezo hakina maudhui.','Template part not found or not stored in the database.'=>'Sehemu ya kiolezo hakipatikani au hakijahifadhiwa kwenye hifadhidata.','Template Parts'=>'Sehemu za Muundo','Templates'=>'Mifano','Test connection'=>'Jaribu muunganisho','Testing…'=>'Inajaribu…','Text domain / locale'=>'Uwanja wa lugha / muktadha','Text to translate'=>'Maandishi ya kutafsiri','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'Cache ya Majibu ya API hifadhi matokeo halisi ya kila ombi la AI — tafsiri, maelezo ya meta, excerpt, na uzalishaji wa maudhui — kwa kutumia hash ya maingizo (maudhui, jozi ya lugha, mtoa huduma, mfano). Maombi yanayofuata yenye maingizo sawa yanatumikia kutoka kwa cache bila kuita API. Cache hii ni tofauti na Kumbukumbu ya Tafsiri: Kumbukumbu ya Tafsiri hufanya kazi kwa kiwango cha blokii na inashirikiana kati ya machapisho; Cache ya Majibu ya API hufanya kazi kwa kiwango cha kipengele na inahifadhiwa kwa kila chapisho.','The editor did not accept the content — please try again.'=>'Mhariri hakukubali maudhui — tafadhali jaribu tena.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Kiwango cha Nuru kinatumia mfano wa haraka uliowekwa kwenye jedwali la Miundo hapo juu (chaguo-msingi: Haiku / Flash). Badilisha kwa Ubora ikiwa unahitaji usahihi wa tafsiri sawa na hali ya ukurasa kamili kwa vipande.','The phrase as it appears in the source text.'=>'Sehemu kama ilivyoonekana katika maandishi ya chanzo.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Lugha kuu daima hutumika kwenye mzizi wa tovuti yako — hakuna kiambishi cha URL katika hali ya njia, hakuna subdomain ya lugha katika hali ya subdomain. Lugha nyingine zote hutumia au kiambishi cha /lang/ (mfano example.com/de/) au subdomain ya lugha (mfano de.example.com), kulingana na mpangilio wa muundo wa URL hapo chini.','The source page has no footnotes.'=>'Ukurasa wa chanzo haujakuwa na nukuu za mguu wa ukurasa.','The upload failed — please try again.'=>'Upakuaji umeshindwa — tafadhali jaribu tena.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Nukuu hizi za mguu wa ukurasa zinatoka kwenye ukurasa wa chanzo na zinaonyeshwa hapa kwa marejeo tu. Ziongeze kwenye ukurasa huu kwa kutumia mhariri wa vikundi.','This is the source page. Footnotes are edited directly in the block editor.'=>'Hii ni ukurasa wa chanzo. Nukuu za mguu wa ukurasa huhaririwa moja kwa moja kwenye mhariri wa vikundi.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Funguo hili kwa sasa linatolewa na seva %s na haliwezi kuondolewa hapa. Ingiza funguo mpya juu ili kuilinda na thamani ya hifadhidata.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tip: ili kurejesha mfano kwa chaguo-msingi cha ndani, safisha uwanja na hifadhi.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Ili kutumia siri ya usimbuaji wa desturi (badala ya thamani ya wp_salt iliyotolewa), ongeza hii katika wp-config.php:','Today'=>'Leo','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Matumizi ya token yamekusanywa kwa kipengele, mtoa huduma, na mfano. Yamehifadhiwa kwenye kila simu ya AI iliyofanikiwa; ping za Jaribio la Muunganisho zinachukuliwa kwa makusudi ili zisibakize jumla. Jedwali la msingi linakusanya kila siku — chagua dirisha chini ili kuangalia.','Tone'=>'Mwelekeo','tone'=>'sauti','Tone:'=>'Sauti:','Too many AI requests. Please retry in %d seconds.'=>'Orodha nyingi za AI. Tafadhali jaribu tena kwa sekunde %d.','Total'=>'Jumla','Total tokens'=>'Jumla ya token','Translate'=>'Tafsiri','Translate / Revise'=>'Tafsiri / Badilisha','Translate / Revise block'=>'Kifungu cha Tafsiri / Badilisha','Translate all'=>'Tafsiri zote','Translate chunk'=>'Tafsiri sehemu','Translate Content'=>'Tafsiri Maudhui','Translate missing'=>'Tafsiri isiyokamilika','Translate page…'=>'Tafsiri ukurasa…','Translated content'=>'Yaliyomo yaliyotafsiriwa','Translated Names'=>'Majina yaliyotafsiriwa','Translated title'=>'Kichwa kilichotafsiriwa','Translated to:'=>'Imetafsiriwa kwa:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Imetafsiriwa. Pitia kwenye Mhariri wa Tovuti — viungo vya ndani, URLs za urambazaji, na majina ya kiolezo hayasaswi kiotomatiki.','Translating…'=>'Inatafsiri…','Translation'=>'Tafsiri','Translation Caching'=>'Kuhifadhi Kumbukumbu za Tafsiri','Translation found but permalink could not be generated'=>'Utaratibu umegunduliwa lakini kiungo cha kudumu hakikuweza kutengenezwa','Translation Limits'=>'Mipaka ya Tafsiri','Translation Limits & Behavior'=>'Mipaka ya Tafsiri & Tabia','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Mipaka ya Tafsiri: kudhibiti ni majukumu ya aina gani za watumiaji wanaweza kuanzisha tafsiri ya AI, na kuweka bajeti ya token kwa mwezi. Kupita bajeti kunasababisha kusitisha simu za AI hadi mwezi ujao utakapobadilika.','Translation Memory'=>'Kumbukumbu ya Tafsiri','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Kumbukumbu za Tafsiri hufanya kazi kwa kuhifadhi matokeo ya AI kwa hash ya maudhui, jozi ya lugha, mtoa huduma, na mfano. Kuhariri chapisho kunavunjilia mbali kumbukumbu ili simu inayofuata ya tafsiri ipate matokeo mapya.','Translation Memory cleared. %d cached block was removed.'=>'Kumbukumbu ya Tafsiri imefutwa. Kipande cha cache %d kiliondolewa.' . "\0" . 'Kumbukumbu ya Tafsiri imefutwa. Vipande %d vya cache vimeondolewa.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Kumbukumbu za Tafsiri: hifadhi chapisho kamili kilichotafsiriwa kwa kila hash ya maudhui. Futa wakati unataka kulazimisha tafsiri upya ya maudhui yote bila kujali kama yaliyobadilika.','Translation workflow'=>'Mchakato wa Tafsiri','Translation, Content Generator'=>'Tafsiri, Mwandishi wa Maudhui','Type'=>'Aina','Uli Hake'=>'Uli Hake','Uninstall Behaviour'=>'Futa Tabia ya Kifuta','Uninstall setting saved.'=>'Mipangilio ya kufuta imesimamiwa.','unknown error'=>'hitilafu isiyojulikana','Unknown provider.'=>'Mtoa huduma haijulikani.','Up'=>'Juu','Upload .mo file'=>'Pakua faili ya .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Pakua faili zilizokusanywa za .mo kubadilisha maneno ya programu za watu wengine kwa maeneo maalum — kwa mfano, tafsiri maalum ya VikBooking inayotumia "apartment" badala ya "room". Faili lazima zifuate muundo wa jina la WordPress: {textdomain}-{locale}.mo (mfano, vikbooking-ca.mo). Zina hifadhiwa kwenye folda ya uploads na huishi baada ya sasisho la programu.','Upload Override'=>'Pakua Mabadiliko','URL could not be mapped to a post — check the link target exists'=>'URL haikuweza kuambatana na chapisho — angalia kama lengo la kiungo lipo','URL structure'=>'Muundo wa URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Muundo wa URL: hali ya kiambatanisho cha njia (example.com/de/) hahitaji mabadiliko ya seva. Hali ya subdomain (de.example.com) inahitaji rekodi ya DNS ya wildcard, cheti cha SSL cha wildcard, na mabadiliko ya usanidi wa seva — angalia mwongozo wa Usanidi wa Seva.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Tumia kanda za juu za ukurasa huu kuunda kila eneo. Mabadiliko kwenye kanda ya Router yanachukua athari mara moja; mabadiliko kwenye funguo za AI na mipangilio ya mfano yanahusiana na ombi lijalo la AI.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Jedwali la istilahi linaloswa na mtumiaji kwa kila lugha. Viingilio vinaongezwa kwenye maelekezo ya mfumo wa tafsiri ili AI itumie maneno yanayopendelewa kwa utaratibu — muhimu kwa msamiati wa sekta ("kWp", "PPA", "sehemu ya kuunganishwa"), majina ya chapa ambayo hayapaswi kutafsiriwa, na maneno ya kanuni za udhibiti zilizowekwa. Sehemu zote za lugha ni hiari: acha "Lugha ya Chanzo" tupu ili kutumia kiingilio bila kujali unapotafsiri kutoka kwa lugha gani; acha "Lugha ya Malengo" tupu ili kuitekeleza kwa lugha zote za malengo kwa pamoja.','Using custom meta description.'=>'Kutumia maelezo maalum ya meta.','View'=>'Tazama','View built-in default'=>'Tazama chaguo-msingi cha kujengwa ndani','View details'=>'Tazama maelezo','View Lingua Forge details'=>'Tazama maelezo ya Lingua Forge','Visit plugin site'=>'Tembelea tovuti ya programu-jalizi','Warning:'=>'Onyo:','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Wakati kumbukumbu za kagua zinapokua zimewezeshwa (kupitia kitufe cha chini au kwa kufafanua LINGUAFORGE_AI_DEBUG katika wp-config.php), vipengele vya Tafsiri na template ya FSE huandika maombi yao ya AI na majibu kwenye diski kwa ajili ya utatuzi wa matatizo. Tumia sehemu hii kufuatilia matokeo hayo na kuyaondoa mara umepata unachohitaji — faili zinaweza kukua kwa haraka kwenye kurasa kubwa. Sanidi saraka ya malengo kupitia kichungi cha linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Wakati kinachozimwa, wageni wa mara ya kwanza wasio na keki ya lugha na bila kiambishi cha lugha kwenye URL wanapelekwa kwa toleo la lugha linalolingana zaidi. Uelekezaji huachwa ikiwa lugha inayopendelewa na kivinjari si miongoni mwa lugha zinazofanya kazi za router. Mara mgeni anapochagua lugha kupitia kisakinishi, keki inachukua kipaumbele na kichwa cha kivinjari hakitazingatiwa kwa ziara zijazo.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Kiwango cha mfano kinachotumika kwa tafsiri ya kurasa kamili. Ubora unatumia mfano uliowekwa kwenye jedwali la Miundo hapo juu na ni wa kupendekezwa kwa tafsiri sahihi, ya muda mrefu. Badilisha kwa Mwanga ikiwa ni haraka au gharama ndogo ndogo ndizo kipaumbele na maudhui ni mafupi.','WP-CLI reference'=>'Rejea ya WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Andika maombi ya AI na majibu kwenye diski kwa ajili ya utatuzi wa matatizo','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Pia unaweza kufafanua funguo kama mabadiliko ya mazingira au mabadiliko ya PHP (mfano katika wp-config.php). Vyanzo hivyo vinatumika kiotomatiki kama mbadala wakati hakuna funguo ya hifadhidata iliyohifadhiwa.','You do not have permission to manage these settings.'=>'Huna ruhusa ya kusimamia mipangilio hii.','You do not have permission to read this post.'=>'Huna ruhusa ya kusoma chapisho hili.','{n} stale path(s)'=>'{n} njia/nyingine zilizobaki','— Any source language —'=>'— Yoyote ya lugha ya chanzo —','— Any target language —'=>'— Yoyote ya lugha ya malengo —','— Any target —'=>'— Malengo yote —','— Any —'=>'— Yoyote —','— auto-detect —'=>'— kugundua kiotomatiki —','— select a language —'=>'— chagua lugha —','— toggle in Settings → Behavior.'=>'— chaguo katika Vipimo → Tabia.','← Back'=>'← Rudi nyuma','↑ Detected from current post'=>'↑ Imegunduliwa kutoka kwa chapisho la sasa','↺ Re-translate'=>'↺ Tafsiri tena','↺ Refine'=>'↺ Boresha','↺ Refresh'=>'↺ Mvua','↺ Refreshing…'=>'↺ Inasasishwa…','⚠ Borderline'=>'Hatari ya ukingo ⚠','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Hakuna machapisho <strong>{lang}</strong> yaliyopatikana. Hakikisha machapisho yote yaliyotafsiriwa yana Meta ya Lugha iliyowekwa kuwa <strong>{lang}</strong> kwenye sanduku la Meta la Lugha.','⚠ No changes'=>'⚠ Hakuna mabadiliko','⚠ No changes — re-scan?'=>'⚠ Hakuna mabadiliko — tena uchunguzi?','✅ Fixed ({n})'=>'✅ Imerekebishwa ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Hakuna viungo vilivyovunjika au makosa ya kiolezo yaliyopatikana kwa <strong>{lang}</strong>. Umechunguza machapisho <strong>{scanned}</strong> na kurasa — ukaguzi wote umepita. Viungo vya sehemu za kiolezo (kichwa, mfinyanzi, upendeleo wa upande) havijajumuishwa hapa — tumia kitufe cha Kutatuwa Sehemu za Kiolezo kuangalia tofauti.','✅ Template fixed'=>'✅ Kiolezo kimerekebishwa','✓ All parts created.'=>'✓ Sehemu zote zimetengenezwa.','✓ All templates created.'=>'✓ Kila kiolezo kimeundwa.','✓ All translated.'=>'✓ Zote zimefasirishwa.','✓ Configured'=>'Imesasishwa','✓ Connection OK'=>'✓ Muunganisho mzuri','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Yaliyomo yamezalishwa — angalia juu ili kuangalia, kuboresha, na kutumia.','✓ Done'=>'✓ Imekamilika','✓ Enabled'=>'✓ Imewashwa','✓ Good length'=>'Urefu mzuri ✓','✓ In safe storage'=>'✓ Katika hifadhi salama','✓ Language installed.'=>'✓ Lugha imewekwa.','✓ Links fixed.'=>'✓ Viungo vimerekebishwa.','✓ Nav refs fixed.'=>'✓ Marejeo ya urambazaji yamerekebishwa.','✓ Parts fixed.'=>'✓ Sehemu zimerekebishwa.','✓ Pattern translated.'=>'✓ Mfano umefasirishwa.','✓ Refined — review the updated draft above.'=>'✓ Umeboreshwa — hakiki rasimu iliyosasishwa hapo juu.','✓ Translation saved'=>'✓ Tafsiri imehifadhiwa','✗ Disabled'=>'✗ Imesimamishwa','✗ Error:'=>'✗ Hitilafu:','✗ Failed:'=>'✗ Imeshindwa:','✗ Not configured'=>'Hijasasishwa','✗ Too long'=>'Mrefu sana ✗','✗ Too short'=>'Mfupi sana ✗','❌ Failed'=>'❌ Imeshindwa','📄 Wrong template'=>'📄 Kiolezo kisicho sahihi','📍 Stale path (page moved)'=>'📍 Njia/nyingine zilizobaki (ukurasa uhamishiwa)']];
